def _ledger(data, sequence_first, original_tax):
    chosen = {}
    cutoff = data.get("cutoff", 10**9)
    for pos, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        if sequence_first:
            key = (sequence, event.get("revision", 0), pos)
        else:
            key = (event.get("revision", 0), pos)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = _round(raw * (10000 - discount), 10000, mode)
        base = raw if original_tax else net
        tax = _round(base * event.get("tax_bp", 0), 10000, mode)
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def _resolver(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    rows = {name: {row["version"]: row for row in versions}
            for name, versions in packages.items()}
    roots = data["roots"]
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})

    # Values are ordered lexicographically by the required version vector.
    domains = []
    for name in names:
        versions = sorted((v for v in rows[name]
                           if v not in blocked.get(name, [])), reverse=True)
        domains.append(versions + [-1])

    import itertools
    for vector in itertools.product(*domains):
        chosen = {name: version for name, version in zip(names, vector)
                  if version != -1}
        if any(name not in chosen or not bounds[0] <= chosen[name] <= bounds[1]
               for name, bounds in roots.items()):
            continue
        if any(name in chosen and chosen[name] != version
               for name, version in pins.items()):
            continue

        edges = {name: [] for name in chosen}
        valid = True
        for name, version in chosen.items():
            for dep in rows[name][version].get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                target = dep["name"]
                installed = chosen.get(target)
                if installed is None or not dep["min"] <= installed <= dep["max"]:
                    valid = False
                    break
                edges[name].append(target)
            if not valid:
                break
        if not valid:
            continue

        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            stack.extend(edges.get(name, []))
        if reachable != set(chosen):
            continue

        finished, active = set(), set()
        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not visit(dep) for dep in edges[name]):
                return False
            active.remove(name)
            finished.add(name)
            return True
        if not all(visit(name) for name in edges):
            continue
        return {"versions": chosen}
    return {"error": "unsatisfiable"}


def _intervals(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_ids = None
    best_value = None

    import itertools
    available = [job for job in jobs if job["id"] not in blocked]
    for subset in itertools.combinations(available, k):
        ids = tuple(sorted(job["id"] for job in subset))
        idset = set(ids)
        if not mandatory.issubset(idset):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        points = []
        for job in subset:
            points.append((job["start"], 1))
            points.append((job["end"], -1))
        active = 0
        feasible = True
        for _, delta in sorted(points):
            active += delta
            if active > 2:
                feasible = False
                break
        if not feasible:
            continue
        value = sum(job["value"] for job in subset)
        if (best_value is None or value > best_value or
                (value == best_value and ids < best_ids)):
            best_value, best_ids = value, ids
    if best_ids is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def _routes(data):
    import heapq
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source = data["source"]
    initial_mask = bit.get(source, 0)
    initial = (source, initial_mask, data["coupons"])
    dist = {initial: data["start"]}
    queue = [(data["start"], source, initial_mask, data["coupons"])]
    while queue:
        time, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if dist.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], remaining)]
            if remaining:
                duration = max(2, edge["duration"] - edge.get("discount", 0))
                options.append((duration, remaining - 1))
            for duration, left in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                nxt = edge["v"]
                next_mask = mask | bit.get(nxt, 0)
                next_state = (nxt, next_mask, left)
                if arrival < dist.get(next_state, float("inf")):
                    dist[next_state] = arrival
                    heapq.heappush(queue, (arrival, nxt, next_mask, left))
    return {"arrival": None}


